$ErrorActionPreference = "Stop"

$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"
$Version = "4.5.1"

if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}

Write-Host "Installing MNTrapTeam $Version name-matching fix..."

$payload = ""
[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\recent_score_scout_cli.py"),
    [Convert]::FromBase64String($payload)
)

Set-Content -Path (Join-Path $ProjectRoot "VERSION") -Value $Version -Encoding UTF8

$InitFile = Join-Path $ProjectRoot "mntrapteam\__init__.py"
if (Test-Path $InitFile) {
    $t = Get-Content $InitFile -Raw
    if ($t -match '__version__\s*=') {
        $t = [regex]::Replace(
            $t,
            '__version__\s*=\s*["''][^"'']+["'']',
            '__version__ = "4.5.1"',
            1
        )
    } else {
        $t = $t.TrimEnd() + "`r`n__version__ = `"4.5.1`"`r`n"
    }
    Set-Content -Path $InitFile -Value $t -Encoding UTF8
}

$GuiFile = Join-Path $ProjectRoot "mntrapteam\gui.py"
if (Test-Path $GuiFile) {
    $t = Get-Content $GuiFile -Raw
    $t = [regex]::Replace($t, 'MNTrapTeam \d+\.\d+\.\d+', 'MNTrapTeam 4.5.1', 1)
    Set-Content -Path $GuiFile -Value $t -Encoding UTF8
}

Set-Location $ProjectRoot
& ".\.venv\Scripts\python.exe" -m py_compile ".\mntrapteam\recent_score_scout_cli.py"
if ($LASTEXITCODE -ne 0) { throw "Syntax check failed." }

Write-Host ""
Write-Host "MNTrapTeam 4.5.1 installed."
Write-Host "ShootScoreBoard LAST FIRST M names now match FIRST M LAST database names."
Write-Host "Middle initials are ignored; JR/SR suffixes remain identity-sensitive."
Write-Host ""
Write-Host "Next:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.recent_score_scout_cli preview --id-scan 2050:2140'
